export function initializeFields(values={}){
 const result={...values}
 for(const group of maicGroups)for(const field of group.fields){
  if(field.type==='checks' && !Array.isArray(result[field.key]))result[field.key]=[]
  if(field.type==='number' && (result[field.key]===undefined || result[field.key]===''))result[field.key]=null
 }
 return result
}
export function initialFields(event){
 const fields={occurrenceDate:event.dateUnknown?'':event.date,occurrenceTime:event.timeUnknown?'':event.time,place:event.place,position:`${event.lat ?? 'Unknown'}, ${event.lon ?? 'Unknown'} · ${event.positionQuality}`,incidentTypes:[event.type,...(event.secondaryTypes || [])].join(', '),seriousness:event.seriousness,aor:event.aor,homeport:event.homeport,cpc:event.cpc,issuingOffice:event.issuingOffice,occurrenceNarrative:event.summary,initialActions:event.initialActions,recommendations:event.recommendations,informationSources:[event.sourceType,event.sourceRef].filter(Boolean).join(' · '),machineryFactors:[],humanFactors:[],environmentFactors:[]}
 for(const k of ['fatalities','missing','injured','rescued','crew','passengers','totalOnboard']) fields[k]=event.consequences?.[k] ?? null
 fields.damage=event.consequences?.shipCondition || '';fields.pollution=event.consequences?.pollution || ''
 fields.shipParticulars=event.vessels.map(v=>`${v.name || 'Unknown vessel'}; former names: ${v.formerNames || 'Unknown'}; Official: ${v.officialNumber || 'Unknown'}; IMO: ${v.imoNumber || 'Unknown'}; registration: ${v.registrationStatus || 'Unknown'}; rig: ${v.rigType || 'Unknown'}; service: ${v.type || 'Unknown'}; flag: ${v.flag || 'Unknown'}`).join('\n\n')
 fields.construction=event.vessels.map(v=>`${v.name}: built ${v.yearBuilt ?? 'Unknown'} at ${v.buildPlace || 'Unknown'}; hull ${v.hull || 'Unknown'}; L/B/D ${v.length ?? '?'}/${v.breadth ?? '?'}/${v.depth ?? '?'}; GT ${v.grossTonnage ?? 'Unknown'} / NT ${v.netTonnage ?? 'Unknown'} / DWT ${v.deadweight ?? 'Unknown'}; size ${v.sizeClass || 'Unknown'}; class ${v.classificationSociety || 'Unknown'}`).join('\n\n')
 fields.machineryParticulars=event.vessels.map(v=>`${v.name}: ${v.engineCount ?? 'Unknown count'} engines; ${v.engineMake || 'Unknown make'}; ${v.enginePower ?? 'Unknown power'} ${v.enginePowerUnit || ''}; stern ${v.sternType || 'Unknown'}`).join('\n\n')
 fields.ownership=event.vessels.map(v=>`${v.name}: owner ${v.owner || 'Unknown'}; operator ${v.operator || 'Unknown'}; contacts ${v.ownerContact || 'Unknown'} / ${v.operatorAddress || 'Unknown'}; master ${v.masterName || 'Unknown'} / licence ${v.masterLicense || 'Unknown'}`).join('\n\n')
 fields.voyage=event.vessels.map(v=>`${v.name}: ${v.voyage?.origin || 'Unknown origin'} to ${v.voyage?.destination || 'Unknown destination'}; route ${v.voyage?.route || 'Unknown'}; cargo ${v.voyage?.cargoType || 'Unknown'} ${v.voyage?.cargoQuantity ?? ''} ${v.voyage?.cargoUnit || ''}`).join('\n\n')
 return initializeFields(fields)
}
